import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Tentacle - Core RADOS","description":"","frontmatter":{"title":"CDS Tentacle - Core RADOS","date":"2024-08-22T00:00:00.000Z","updated":"2024-08-23T00:00:00.000Z","tags":["Ceph","分布式存储","RADOS","E优化","QoS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/CDS_Tentacle_-_Core_RADOS.md","filePath":"posts/2024/CDS_Tentacle_-_Core_RADOS.md","lastUpdated":1780459816000}'),r={name:"posts/2024/CDS_Tentacle_-_Core_RADOS.md"};function p(n,l,s,a,u,S){return t(),e("div",null,[...l[0]||(l[0]=[o('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>本次Ceph项目开发会议主要讨论了多个关键议题，包括E优化、零压缩、编码增强、PG池稳定性、QoS改进、Scrub改进、MGR改进、NVMe-oF网关、Upmap平衡器、监控器配置配置文件、随机化、需要兼容的客户端以及发布等。</p><p><strong>1. E优化</strong>：</p><ul><li>讨论了成本优化和性能限制，重点关注优化方案的成本效益。</li><li>Bill Scales提供了详细的设计文档，介绍了优化方案的主要思想。</li><li>讨论了增加chunk size的益处，以及如何降低优化过程中引入的风险。</li><li>确定了默认EC插件切换方案。</li></ul><p><strong>2. 零压缩</strong>：</p><ul><li>讨论了在消息缓冲列表和对象存储路径中压缩零数据，以提高性能。</li><li>讨论了优化方案将受益于增加chunk size，因此压缩零数据将非常有用。</li><li>需要解决缓冲列表中零数据的压缩问题，包括编码和接口问题。</li><li>可能需要新的消息类型或协议级别来支持压缩。</li></ul><p><strong>3. 编码增强</strong>：</p><ul><li>继续推进Squid项目的编码增强工作。</li><li>Naiton在对象存储库中添加了缺失的类型，并进行了测试以确保兼容性。</li><li>需要继续扩展测试范围，包括使用旧编码器验证新编码器生成的字节流。</li></ul><p><strong>4. PG池</strong>：</p><ul><li>讨论PG池的稳定性改进。</li><li>已有PR对PG池T方案进行了重构，以支持未来的扩展。</li></ul><p><strong>5. QoS</strong>：</p><ul><li>讨论QoS的改进，包括操作、回填操作、客户端API和RBD图像级别QoS。</li><li>已有PR对QoS功能进行了改进，包括改进回填操作和客户端API。</li><li>需要进一步研究RBD图像级别QoS的实现方案。</li></ul><p><strong>6. Scrub</strong>：</p><ul><li>讨论Scrub的改进，包括拆分存储、设计Scrub队列和改进Deep Scrub调度。</li><li>将Scrub存储拆分为浅层错误和深层错误。</li><li>设计Scrub队列，以简化代码并提高可理解性。</li><li>改进Deep Scrub调度，以提供更好的控制。</li></ul><p><strong>7. MGR</strong>：</p><ul><li>讨论MGR的改进，包括操作跟踪器、统计周期和依赖性。</li><li>已在Squid中引入了操作跟踪器，用于跟踪操作和请求。</li><li>需要进一步研究提供更细粒度跟踪的需求。</li><li>需要改进MGR统计周期的文档，以便在MGR不可用时获取数据。</li></ul><p><strong>8. NVMe-oF网关</strong>：</p><ul><li>讨论NVMe-oF网关的改进，包括可选服务选择和移除。</li><li>可以在运行时选择启用或禁用某些服务。</li><li>可以将NVMe-oF网关服务从监控器中移除。</li></ul><p><strong>9. Upmap平衡器</strong>：</p><ul><li>讨论Upmap平衡器的改进，以提高可伸缩性。</li><li>可以使用多线程来提高Upmap平衡器的性能。</li></ul><p><strong>10. 监控器配置配置文件</strong>：</p><ul><li>讨论监控器配置配置文件的实现。</li><li>可以实现监控器配置配置文件，以简化配置管理。</li></ul><p><strong>11. 随机化</strong>：</p><ul><li>讨论监控器随机化的问题。</li><li>监控器重新部署时可能会遇到连接问题。</li><li>可以通过引入非通配符地址来解决这个问题。</li></ul><p><strong>12. 需要兼容的客户端</strong>：</p><ul><li>讨论需要兼容的客户端的机制。</li><li>需要考虑如何强制执行客户端兼容性。</li><li>可以使用特征位而不是代码名称来强制执行客户端兼容性。</li></ul><p><strong>13. 发布</strong>：</p><ul><li>讨论Tentacle版本的发布。</li><li>需要确定负责发布Tentacle版本的人员。</li></ul><p>本次会议还讨论了其他多个议题，包括Scrub、MGR、NVMe-oF网关、Upmap平衡器、监控器配置配置文件、随机化、需要兼容的客户端以及发布等。会议确定了后续行动计划，并分配了责任。</p>',29)])])}const g=i(r,[["render",p]]);export{c as __pageData,g as default};
